CREATE TABLE `divisis` (
  `id` bigint UNSIGNED NOT NULL,
  `nama` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `slug` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `ikon` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `header` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `deskripsi` text COLLATE utf8mb4_unicode_ci,
  `view_file` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'divisi.show',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `urutan` int NOT NULL DEFAULT '0',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `background_image` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `stats` json DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Dumping data for table `divisis`
--

INSERT INTO `divisis` (`id`, `nama`, `slug`, `ikon`, `header`, `deskripsi`, `view_file`, `is_active`, `urutan`, `created_at`, `updated_at`, `background_image`, `stats`) VALUES
(11, 'Divisi Riset dan Inovasi', 'divisi-riset-dan-inovasi', NULL, 'Divisi Riset dan Inovasi', '<p>Divisi Riset dan Inovasi berkomitmen mengembangkan pengetahuan melalui penelitian berkualitas tinggi dan inovasi berkelanjutan untuk kemajuan bangsasa.</p>', 'divisi.show', 1, 1, '2026-07-29 13:28:12', '2026-08-02 16:50:20', 'divisi_heroes/ShnkFZTwZWJH50nTrhmEcveRVODDLFo4PAVscis0.png', '[{\"label\": \"Penelitians\", \"number\": \"150+\"}, {\"label\": \"Publikasi\", \"number\": \"50+\"}, {\"label\": \"Mitra\", \"number\": \"300+\"}, {\"label\": \"Alumni\", \"number\": \"1000+\"}]'),
(12, 'Divisi Publikasi dan HKI', 'divisi-publikasi-dan-hki', NULL, 'Divisi Publikasi dan HKI', '<p>Divisi Publikasi dan HKI mendukung diseminasi hasil riset dan perlindungan hak kekayaan intelektual dari para peneliti dan akademisi.</p>', 'divisi.show', 1, 2, '2026-07-29 13:28:12', '2026-07-29 16:47:24', 'divisi_heroes/aWVlKMx3QaUbKjE37bNZH9inTIL8b6ougcHa8oMG.jpg', '[{\"label\": \"Jurnal\", \"number\": \"200+\"}, {\"label\": \"Paten\", \"number\": \"45\"}, {\"label\": \"Buku\", \"number\": \"60\"}, {\"label\": \"HKI\", \"number\": \"85\"}]'),
(13, 'Divisi Pengembangan SDM', 'divisi-pengembangan-sdm', NULL, 'Divisi Pengembangan SDM', '<p>Divisi Pengembangan SDM fokus pada peningkatan kapasitas dan kompetensi sumber daya manusia melalui program pelatihan berkelanjutan.</p>', 'divisi.show', 1, 3, '2026-07-29 13:28:12', '2026-07-29 16:53:16', 'divisi_heroes/NkBkvFvWis5nItn2znlAT8xiFnVU8UsAliE9F0jt.png', '[{\"label\": \"Peserta\", \"number\": \"500+\"}, {\"label\": \"Program\", \"number\": \"25\"}, {\"label\": \"Trainer\", \"number\": \"40\"}, {\"label\": \"Kepuasan\", \"number\": \"95%\"}]'),
(14, 'Divisi Vokasi dan Sertifikasi', 'divisi-vokasi-dan-sertifikasi', NULL, 'Divisi Vokasi dan Sertifikasi', '<p>Divisi Vokasi dan Sertifikasi menyediakan program pelatihan dan sertifikasi profesional yang relevan dengan kebutuhan industri.</p>', 'divisi.show', 1, 4, '2026-07-29 13:28:12', '2026-07-29 17:05:38', 'divisi_heroes/U8pwjhHgtJlCAay2d2dhseagbjY1Gvha6SSWgkrQ.png', '[{\"label\": \"Lulusan\", \"number\": \"300+\"}, {\"label\": \"Sertifikasi\", \"number\": \"15\"}, {\"label\": \"Terserap\", \"number\": \"80%\"}, {\"label\": \"Industri\", \"number\": \"20\"}]'),
(15, 'Divisi Sains Data dan TI', 'divisi-sains-data-dan-ti', NULL, 'Divisi Sains Data dan TI', '<p>Divisi Sains Data dan TI mengembangkan solusi teknologi informasi dan analitik data untuk transformasi digital organisasi modern.</p>', 'divisi.show', 1, 5, '2026-07-29 13:28:12', '2026-07-29 17:11:18', 'divisi_heroes/sZtiSgnH65YArsnLUhOOAbxLefN9C1B6quSxhrOO.png', '[{\"label\": \"Project\", \"number\": \"100+\"}, {\"label\": \"Klien\", \"number\": \"50\"}, {\"label\": \"Developer\", \"number\": \"25\"}, {\"label\": \"Uptime\", \"number\": \"99%\"}]'),
(16, 'Divisi Bahasa, Seni dan Budaya', 'divisi-bahasa-seni-dan-budaya', NULL, 'Divisi Bahasa, Seni dan Budaya', '<p>Divisi Bahasa, Seni dan Budaya melestarikan dan mengembangkan warisan budaya lokal melalui riset dan dokumentasi sistematis.</p>', 'divisi.show', 1, 6, '2026-07-29 13:28:12', '2026-07-29 17:20:31', 'divisi_heroes/BUGnVCCX9KDj73lnHHY8wCQqMK48srnWE5AfXRix.png', '[{\"label\": \"Bahasa\", \"number\": \"35\"}, {\"label\": \"Dokumen\", \"number\": \"200+\"}, {\"label\": \"Event\", \"number\": \"15\"}, {\"label\": \"Peserta\", \"number\": \"1000+\"}]'),
(17, 'Divisi Kerja Sama dan HI', 'divisi-kerja-sama-dan-hi', NULL, 'Divisi Kerja Sama dan HI', '<p>Divisi Kerja Sama dan HI membangun kolaborasi nasional dan internasional untuk memperkuat jaringan akademis dan riset global.</p>', 'divisi.show', 1, 7, '2026-07-29 13:28:12', '2026-07-29 17:34:17', 'divisi_heroes/OldQT9zkyRMqCyVn3cbazxsAaou0w3o7LMM7MrNT.png', '[{\"label\": \"Negara\", \"number\": \"50+\"}, {\"label\": \"Mitra\", \"number\": \"100+\"}, {\"label\": \"MoU\", \"number\": \"80\"}, {\"label\": \"Kolaborasi\", \"number\": \"200+\"}]'),
(18, 'Divisi Konsultan', 'divisi-konsultan', NULL, 'Divisi Konsultan', '<p>Divisi Konsultan memberikan layanan konsultasi ahli untuk berbagai kebutuhan organisasi publik dan privat dengan solusi yang terukur.</p>', 'divisi.show', 1, 8, '2026-07-29 13:28:12', '2026-07-29 17:39:36', 'divisi_heroes/b6JoLB7HUYdlLvBDhmQRbCVTuIT8CLFEcOwzVCrg.png', '[{\"label\": \"Klien\", \"number\": \"500+\"}, {\"label\": \"Ahli\", \"number\": \"30\"}, {\"label\": \"Project\", \"number\": \"1000+\"}, {\"label\": \"Sukses\", \"number\": \"90%\"}]'),
(19, 'Divisi Karir dan Kewirausahaan', 'divisi-karir-dan-kewirausahaan', NULL, 'Divisi Karir dan Kewirausahaan', '<p>Divisi Karir dan Kewirausahaan mendukung pengembangan karir dan ekosistem kewirausahaan untuk menciptakan entrepreneur muda berbakat.</p>', 'divisi.show', 1, 9, '2026-07-29 13:28:12', '2026-07-29 17:49:05', 'divisi_heroes/7E9ZxUkSTr3ESgEsF5UR9rEcnuBoJ67ALTyGqrAz.jpg', '[{\"label\": \"Alumni\", \"number\": \"2000+\"}, {\"label\": \"Startup\", \"number\": \"300+\"}, {\"label\": \"Mentee\", \"number\": \"50\"}, {\"label\": \"Terserap\", \"number\": \"95%\"}]');

