--
-- Table structure for table `divisi_sections`
--

CREATE TABLE `divisi_sections` (
  `id` bigint UNSIGNED NOT NULL,
  `divisi_id` bigint UNSIGNED NOT NULL,
  `section_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `content` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `image` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `urutan` int NOT NULL DEFAULT '0',
  `design_style` enum('light','dark','accent') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'light',
  `position_after` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'before_program',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Dumping data for table `divisi_sections`
--

INSERT INTO `divisi_sections` (`id`, `divisi_id`, `section_name`, `content`, `image`, `urutan`, `design_style`, `position_after`, `is_active`, `created_at`, `updated_at`) VALUES
(4, 11, 'Tentang Divisi', '<p style=\"margin: 0px 0in 10px; color: rgb(0, 0, 0); font-size: 14px; font-family: Roboto, sans-serif; text-align: justify;\"><span style=\"font-family: Arial, Helvetica, sans-serif;\"><span style=\"font-size: 16px;\">Divisi Riset dan Inovasi Denpasar Institute berperan sebagai pusat pengembangan pengetahuan, penelitian, dan solusi berbasis data untuk menjawab berbagai tantangan sosial, ekonomi, dan industri. Melalui pendekatan riset yang aplikatif, divisi ini mentransformasi ide menjadi tindakan nyata—dari tahap identifikasi fenomena hingga perumusan rekomendasi strategis bagi pemangku kepentingan.</span></span></p><p style=\"margin: 0px 0in 10px; color: rgb(0, 0, 0); font-size: 14px; font-family: Roboto, sans-serif; text-align: justify;\"><span style=\"font-family: Arial, Helvetica, sans-serif;\"><span style=\"font-size: 16px;\">Fokus riset meliputi bidang Sumber Daya Manusia, Pariwisata, Pendidikan, Pertanian, Penjaminan Mutu, Keuangan, Kesehatan, Ekonomi, Kebijakan Publik, serta berbagai program riset akademik dan hibah penelitian yang mendukung kegiatan ilmiah dan tugas akhir mahasiswa.</span></span></p>', 'divisi_11_sections/6Boc0pmLhq0BBYhlwMqkVN1h5H3wbtNFINMtncut.png', 1, 'light', 'before_program', 1, '2026-07-29 14:19:27', '2026-08-02 21:50:50'),
(5, 11, 'Keunggulan Divisi', '<p style=\"margin: 0px 0in 10px; color: rgb(0, 0, 0); font-size: 14px; font-family: Roboto, sans-serif; text-align: justify;\"><span style=\"font-family: Arial, Helvetica, sans-serif;\"><span style=\"font-size: 16px;\">Keunggulan Divisi Riset dan Inovasi terletak pada kemampuannya menghadirkan <strong style=\"font-weight: bold;\">solusi riset yang terintegrasi</strong>, didukung oleh:</span></span></p><ul style=\"color: rgb(0, 0, 0); margin-bottom: 10px; font-family: Poppins-Regular; font-size: 14px;\"><li style=\"text-align: justify;\"><span style=\"font-family: Arial, Helvetica, sans-serif;\"><span style=\"font-size: 16px;\">Desain riset yang tepat dan relevan dengan kebutuhan klien dan industri.</span></span></li><li style=\"text-align: justify;\"><span style=\"font-family: Arial, Helvetica, sans-serif;\"><span style=\"font-size: 16px;\">Fasilitas riset modern serta dukungan teknologi analisis data yang akurat.</span></span></li><li style=\"text-align: justify;\"><span style=\"font-family: Arial, Helvetica, sans-serif;\"><span style=\"font-size: 16px;\">Tim peneliti profesional dari berbagai disiplin ilmu yang berkompeten dalam merancang, melaksanakan, dan menginterpretasi hasil riset.</span></span></li></ul>', 'divisi_11_sections/UaDG9gmxYxGHOvWfdjotI4yNcXDEmH2qXK0QMeaW.png', 2, 'accent', 'before_program', 1, '2026-07-29 14:21:23', '2026-07-29 17:58:42'),
(8, 11, 'Kolaborasi dan Keanggotaan', '<p style=\"margin: 0px 0in 10px; color: rgb(0, 0, 0); font-size: 14px; font-family: Roboto, sans-serif; text-align: justify;\"><span style=\"font-family: Arial, Helvetica, sans-serif;\"><span style=\"font-size: 16px;\">Divisi Riset dan Inovasi Denpasar Institute membuka peluang bagi akademisi, peneliti independen, maupun praktisi industri untuk bergabung sebagai <strong style=\"font-weight: bold;\">konsultan, narasumber, atau peneliti mitra</strong>. Partisipasi dapat dilakukan melalui program riset kolaboratif atau kontribusi karya ilmiah untuk dipublikasikan di portal berita dan jurnal ilmiah Denpasar Institute.</span></span></p><p style=\"margin: 0px 0in 10px; color: rgb(0, 0, 0); font-size: 14px; font-family: Roboto, sans-serif; text-align: justify;\"><span style=\"font-family: Arial, Helvetica, sans-serif;\"><span style=\"font-size: 16px;\">Untuk informasi lebih lanjut mengenai program riset, kolaborasi pusat kajian, atau layanan konsultasi, silakan menghubungi tim Divisi Riset dan Inovasi Denpasar Institute.</span></span></p><p style=\"margin: 0px 0in 10px; color: rgb(0, 0, 0); font-size: 14px; font-family: Roboto, sans-serif; text-align: justify;\"><span style=\"font-family: Arial, Helvetica, sans-serif;\"><span style=\"font-size: 16px;\">Kami siap menjadi mitra strategis Anda dalam merancang, melaksanakan, dan mengembangkan riset yang berdampak nyata bagi masyarakat dan pembangunan berkelanjutan.</span></span></p>', NULL, 4, 'accent', 'after_program', 1, '2026-07-29 16:34:24', '2026-07-29 18:00:10'),
(9, 12, 'Tentang Divisi', '<p><strong style=\"font-weight: bold; color: rgb(0, 0, 0); font-family: Roboto, sans-serif; font-size: 14px;\">Divisi Publikasi dan Hak Kekayaan Intelektual (HKI)</strong><span style=\"color: rgb(0, 0, 0); font-family: Roboto, sans-serif; font-size: 14px;\"> di Denpasar Institute berfokus pada pengelolaan dan perlindungan hak kekayaan intelektual serta publikasi karya ilmiah dan kreatif yang dihasilkan oleh institusi dan para pihak terkait. Kami memberikan layanan untuk memastikan bahwa karya cipta, penelitian, dan inovasi yang dihasilkan oleh individu atau organisasi terlindungi secara hukum, serta mendapatkan eksposur yang maksimal melalui berbagai saluran publikasi yang tepat. Divisi ini menggabungkan pengetahuan tentang hak cipta, paten, merek dagang, dan publikasi ilmiah untuk mendukung perkembangan dan kemajuan industri kreatif dan akademik.</span></p>', 'divisi_12_sections/SqgEaqmSptafzi5JUltbHCydxGWZfCANz2O4P7UG.png', 0, 'light', 'before_program', 1, '2026-07-29 16:47:57', '2026-08-02 21:52:29'),
(11, 13, 'Tentang Divisi', '<p style=\"margin: 0px 0in 10px; color: rgb(0, 0, 0); font-size: 14px; font-family: Roboto, sans-serif; text-align: justify;\"><span style=\"font-family: Arial, Helvetica, sans-serif;\"><span style=\"font-size: 16px;\">Divisi Pengembangan SDM Denpasar Institute berfokus pada peningkatan kompetensi, produktivitas, dan profesionalisme individu maupun organisasi. Di era Revolusi Digital dan AI, hubungan antara perusahaan dan karyawan menjadi semakin dinamis dengan tuntutan kinerja yang tinggi. Oleh karena itu, pengembangan SDM menjadi faktor strategis dalam menjaga daya saing dan keberlanjutan bisnis.</span></span></p><p style=\"margin: 0px 0in 10px; color: rgb(0, 0, 0); font-size: 14px; font-family: Roboto, sans-serif; text-align: justify;\"><span style=\"font-family: Arial, Helvetica, sans-serif;\"><span style=\"font-size: 16px;\">Denpasar Institute hadir sebagai mitra strategis bagi perusahaan dalam merancang dan melaksanakan program pengembangan SDM yang terstruktur dan relevan dengan kebutuhan industri.<br>Tujuan utama pengembangan SDM kami meliputi:</span></span></p><ul style=\"color: rgb(0, 0, 0); margin-bottom: 10px; font-family: Poppins-Regular; font-size: 14px;\"><li style=\"text-align: justify;\"><span style=\"font-family: Arial, Helvetica, sans-serif;\"><span style=\"font-size: 16px;\">Peningkatan motivasi dan loyalitas karyawan</span></span></li><li style=\"text-align: justify;\"><span style=\"font-family: Arial, Helvetica, sans-serif;\"><span style=\"font-size: 16px;\">Penguatan kompetensi teknis dan manajerial</span></span></li><li style=\"text-align: justify;\"><span style=\"font-family: Arial, Helvetica, sans-serif;\"><span style=\"font-size: 16px;\">Pengembangan karakter dan etika profesional</span></span></li><li style=\"text-align: justify;\"><span style=\"font-family: Arial, Helvetica, sans-serif;\"><span style=\"font-size: 16px;\">Peningkatan produktivitas dan efektivitas kerja</span></span></li><li style=\"text-align: justify;\"><span style=\"font-family: Arial, Helvetica, sans-serif;\"><span style=\"font-size: 16px;\">Penguatan kolaborasi tim dan sistem manajemen SDM</span></span></li></ul>', 'divisi_13_sections/kifTARLAFtuyQngjt6zlWf1ryl80zirhQ1A2pGdR.png', 0, 'accent', 'before_program', 1, '2026-07-29 16:54:09', '2026-08-02 21:53:20'),
(13, 14, 'Tentang Divisi', '<p style=\"margin: 0px 0px 10px; color: rgb(0, 0, 0); font-size: 14px; font-family: Roboto, sans-serif; text-align: justify;\"><span style=\"font-size: 18px;\">Divisi Vokasi dan Sertifikasi Denpasar Institute merupakan unit pelaksana pendidikan yang berfokus pada pengembangan kompetensi praktis dan profesional melalui program vokasi serta sertifikasi berbasis kompetensi nasional dan internasional. Divisi ini hadir sebagai wujud komitmen Denpasar Institute dalam menciptakan sumber daya manusia yang unggul, adaptif, dan siap bersaing di dunia kerja serta industri kreatif, khususnya di Bali dan Indonesia pada umumnya.</span></p><p style=\"margin: 0px 0px 10px; color: rgb(0, 0, 0); font-size: 14px; font-family: Roboto, sans-serif; text-align: justify;\"><span style=\"font-size: 18px;\">Pendekatan pembelajaran di Divisi Vokasi dan Sertifikasi berlandaskan pada prinsip learning by doing, keterhubungan dengan dunia industri, serta pengembangan potensi individu. Setiap program dirancang untuk mengintegrasikan kemampuan akademik, keterampilan teknis, dan karakter profesional melalui proses pembelajaran yang aplikatif, fleksibel, dan relevan dengan kebutuhan pasar kerja.</span></p>', 'divisi_14_sections/CnfSUIzfi4jPBobBh38tEMU8z4CmGMsVwdCofUVC.png', 0, 'light', 'before_program', 1, '2026-07-29 17:06:36', '2026-08-02 21:54:14'),
(15, 14, 'Kemitraan dan Sertifikasi', '<p style=\"margin: 0px 0px 10px; color: rgb(0, 0, 0); font-size: 14px; font-family: Roboto, sans-serif; text-align: justify;\"><span style=\"font-size: 18px;\">Divisi Vokasi dan Sertifikasi Denpasar Institute bekerja sama dengan:<br>•    Lembaga Sertifikasi Profesi (LSP) terlisensi BNSP,<br>•    Industri kreatif lokal dan pelaku UMKM Bali,<br>•    Asosiasi profesi dan lembaga pendidikan vokasi nasional,</span></p><p style=\"margin: 0px 0px 10px; color: rgb(0, 0, 0); font-size: 14px; font-family: Roboto, sans-serif; text-align: justify;\"><span style=\"font-size: 18px;\">Kerja sama ini memastikan setiap peserta tidak hanya memperoleh pengalaman belajar yang aplikatif, tetapi juga sertifikat kompetensi resmi sebagai pengakuan kemampuan profesional.</span></p><p style=\"margin: 0px 0px 10px; color: rgb(0, 0, 0); font-size: 14px; font-family: Roboto, sans-serif; text-align: justify;\"><span style=\"font-size: 18px;\">Untuk informasi program, jadwal pelatihan, serta rincian biaya, silakan menghubungi tim Divisi Vokasi dan Sertifikasi Denpasar Institute.</span></p><p style=\"margin: 0px 0px 10px; color: rgb(0, 0, 0); font-size: 14px; font-family: Roboto, sans-serif; text-align: justify;\"><span style=\"font-size: 18px;\">Kami siap mendampingi Anda untuk mengembangkan potensi dan memperoleh sertifikasi kompetensi yang relevan dengan dunia kerja dan industri masa depan.</span></p>', NULL, 0, 'dark', 'before_program', 1, '2026-07-29 17:07:55', '2026-07-29 17:57:04'),
(16, 15, 'Tentang Divisi', '<p style=\"margin: 0px 0in 10px; color: rgb(0, 0, 0); font-size: 14px; font-family: Roboto, sans-serif; text-align: justify;\"><span style=\"font-family: Arial, Helvetica, sans-serif;\"><span style=\"font-size: 16px;\">Divisi Sains Data dan Teknologi Denpasar Institute merupakan pengembangan dari Pusat Sains Data dan Teknologi Informasi (PUSDATIN) yang dibentuk berdasarkan Surat Keputusan Ketua Yayasan Guna Widya Paramesthi No. 009/KEP/ADM/02.II/2020 tanggal 2 Februari 2020.</span></span></p><p style=\"margin: 0px 0in 10px; color: rgb(0, 0, 0); font-size: 14px; font-family: Roboto, sans-serif; text-align: justify;\"><span style=\"font-family: Arial, Helvetica, sans-serif;\"><span style=\"font-size: 16px;\">Divisi ini berperan dalam pengelolaan, pengembangan, dan pemanfaatan data serta teknologi informasi untuk mendukung kegiatan akademik, riset, dan administrasi di lingkungan Denpasar Institute.</span></span></p><p style=\"margin: 0px 0in 10px; color: rgb(0, 0, 0); font-size: 14px; font-family: Roboto, sans-serif; text-align: justify;\"><span style=\"font-family: Arial, Helvetica, sans-serif;\"><span style=\"font-size: 16px;\">Selain fungsi manajerial data, divisi ini juga menyelenggarakan <strong style=\"font-weight: bold;\">p</strong>rogram pendidikan vokasi dan pelatihan profesional di bidang sains data dan teknologi informasi, guna menyiapkan SDM yang kompeten di era digital.</span></span></p>', 'divisi_15_sections/TZ1iGIQnpn2pzFTiQhFqaONoemJLT2qDkl3G9Q4B.png', 0, 'light', 'before_program', 1, '2026-07-29 17:11:56', '2026-08-02 21:55:00'),
(17, 15, 'Tugas dan Fungsi Utama', '<ul style=\"color: rgb(0, 0, 0); margin-bottom: 10px; font-family: Poppins-Regular; font-size: 14px;\"><li style=\"text-align: justify;\"><span style=\"font-family: Arial, Helvetica, sans-serif;\"><span style=\"font-size: 16px;\">Mengembangkan dan mengimplementasikan sistem sains data serta teknologi informasi di lingkungan institusi.</span></span></li><li style=\"text-align: justify;\"><span style=\"font-family: Arial, Helvetica, sans-serif;\"><span style=\"font-size: 16px;\">Melaksanakan program pendidikan, pelatihan, dan sertifikasi di bidang data science dan IT.</span></span></li><li style=\"text-align: justify;\"><span style=\"font-family: Arial, Helvetica, sans-serif;\"><span style=\"font-size: 16px;\">Mengelola dan menganalisis data internal maupun eksternal untuk mendukung kebijakan berbasis data (<em>data-driven decision making</em>).</span></span></li><li style=\"text-align: justify;\"><span style=\"font-family: Arial, Helvetica, sans-serif;\"><span style=\"font-size: 16px;\">Melaksanakan evaluasi dan peningkatan berkelanjutan terhadap sistem informasi dan teknologi yang digunakan.</span></span></li><li style=\"text-align: justify;\"><span style=\"font-family: Arial, Helvetica, sans-serif;\"><span style=\"font-size: 16px;\">Menjamin akuntabilitas serta keamanan data institusi.</span></span></li></ul>', NULL, 0, 'accent', 'before_program', 1, '2026-07-29 17:12:43', '2026-07-29 17:55:21'),
(19, 16, 'Tentang Divisi', '<p style=\"margin: 0px 0px 10px; color: rgb(0, 0, 0); font-size: 14px; font-family: Roboto, sans-serif; text-align: justify;\"><span style=\"font-size: 18px;\"><strong style=\"font-weight: bold;\">Divisi Bahasa, Seni dan Budaya (DBSB) </strong>Denpasar Institute merupakan unit kerja yang bertanggung jawab melakukan kajian empiris bidang bahasa, seni dan budaya. DBSB menyelenggarakan kursus persiapan <strong style=\"font-weight: bold;\"><em>TOEFL, IELTS, Marlins Test </em></strong>dan <strong style=\"font-weight: bold;\">Jasa Penerjemahan</strong>.</span></p><p style=\"margin: 0px 0px 10px; color: rgb(0, 0, 0); font-size: 14px; font-family: Roboto, sans-serif; text-align: justify;\"><span style=\"font-size: 18px;\">DBSB menyediakan layanan kursus bahasa asing dan program Bahasa Indonesia untuk Penutur Asing <strong style=\"font-weight: bold;\">(BIPA)</strong> sesuai dengan kurikulum dan standar pembelajaran dari Kementerian Pendidikan dan Kebudayaan. Terkait bidang seni dan budaya, PBSB membuka kursus melukis dan menari.</span></p><p style=\"margin: 0px 0px 10px; color: rgb(0, 0, 0); font-size: 14px; font-family: Roboto, sans-serif; text-align: justify;\"><span style=\"font-size: 18px;\">DBSB merancang program kursus bahasa asing dan program BIPA berbasis <strong style=\"font-weight: bold;\"><em>Classroom Action Research</em></strong> dan mengkolaborasikannya dengan kurikulum standar internasional.</span></p><p style=\"margin: 0px 0px 10px; color: rgb(0, 0, 0); font-size: 14px; font-family: Roboto, sans-serif; text-align: justify;\"><span style=\"font-size: 18px;\">Untuk mengoptimalkan proses pembelajaran, kami menempatkan pengajar yang sudah lulus <strong style=\"font-weight: bold;\"><em>TOEFL</em></strong> atau <strong style=\"font-weight: bold;\"><em>IELTS</em></strong> dan bergelar master (S2) untuk mendampingi siswa secara interaktif.</span></p><p style=\"margin: 0px 0px 10px; color: rgb(0, 0, 0); font-size: 14px; font-family: Roboto, sans-serif; text-align: justify;\"><span style=\"font-size: 18px;\">Bagi DBSB, hubungan antara pengajar dengan siswa dalam proses pembelajaran adalah hubungan interaktif untuk tujuan bersama, yakni mencapai target kompeten. Kompeten dalam berkomunikasi dan kompeten dalam memperoleh standar TOEFL/IELTS untuk kuliah di Australia, Inggris, Selandia Baru atau Amerika, N4 untuk kuliah di Jepang, dan B2 untuk kuliah di Jerman.</span></p><p style=\"margin: 0px 0px 10px; color: rgb(0, 0, 0); font-size: 14px; font-family: Roboto, sans-serif; text-align: justify;\"><span style=\"font-size: 18px;\">Untuk memberikan suasana nyaman saat belajar, <strong style=\"font-weight: bold;\">PBSB</strong> menyediakan fasilitas pembelajaran dengan melengkapi AC di tiap ruang kelas, LCD, <em>moveable audiovisual, whiteboard, pointer, video</em> dan sarana pendukung lainnya. Selain itu, pembelajaran bahasa dikolaborasikan dengan kegiatan budaya seperti acara <em>Halloween, Thanksgiving, Valentine’s Day, Imlek</em>, dan <em>Table Manner</em> untuk memudahkan pemahaman belajar bahasa. </span></p><p style=\"margin: 0px 0px 10px; color: rgb(0, 0, 0); font-size: 14px; font-family: Roboto, sans-serif; text-align: justify;\"><span style=\"font-size: 18px;\">Dengan kegiatan interaktif dalam konteks budaya, lokasi yang strategis dan konsultasi gratis di luar jam kelas, DBSB<strong style=\"font-weight: bold;\"> </strong>sudah dan terus menerima kepercayaan masyarakat sebagai lembaga bahasa yang kredibel.</span></p>', 'divisi_16_sections/iXo1oScmYFlD8yq05i8SMFF0zCVRiyo5ocq37RT9.png', 0, 'light', 'before_program', 1, '2026-07-29 17:21:08', '2026-08-02 21:55:41'),
(20, 16, 'Keunggulan Divisi', '<p style=\"margin: 0px 0px 10px; color: rgb(0, 0, 0); font-size: 14px; font-family: Roboto, sans-serif; text-align: justify;\"><span style=\"font-size: 18px;\">Catat keunggulan kami di bawah ini:</span></p><ol style=\"color: rgb(0, 0, 0); margin-bottom: 10px; font-family: Poppins-Regular; font-size: 14px;\"><li style=\"text-align: justify;\"><span style=\"font-size: 18px;\">Program layanan bahasa berdasarkan <strong style=\"font-weight: bold;\"><em>Classroom Action Research dan Kajian Empiris</em></strong></span></li><li style=\"text-align: justify;\"><span style=\"font-size: 18px;\">Ruang Kelas Nyaman </span></li><li style=\"text-align: justify;\"><span style=\"font-size: 18px;\">Pengajar sudah lulus TOEFL/IELTS dan bergelar master</span></li><li style=\"text-align: justify;\"><span style=\"font-size: 18px;\">Silabus berstandar internasional </span></li><li style=\"text-align: justify;\"><span style=\"font-size: 18px;\">Pendampingan belajar dengan materi yang dinamis dan milenial</span></li><li style=\"text-align: justify;\"><span style=\"font-size: 18px;\">Kegiatan kolaboratif antara pembelajaran bahasa dengan pemahaman seni dan lintas budaya</span></li></ol>', NULL, 0, 'accent', 'before_program', 1, '2026-07-29 17:27:16', '2026-07-29 17:27:16'),
(21, 17, 'Tentang Divisi', '<p style=\"margin: 0px 0in 10px; color: rgb(0, 0, 0); font-size: 14px; font-family: Roboto, sans-serif;\"><span style=\"font-size: 11pt;\"><span style=\"font-family: Calibri, sans-serif;\">Divisi Kerja Sama dan Hubungan Internasional bertanggung jawab atas pelaksanaandan pengembangan kerja sama dengan lembaga-lembaga, organisasi, dan institusi baik di dalam negeri maupun di luar negeri.</span></span></p><ol style=\"color: rgb(0, 0, 0); margin-bottom: 10px; font-family: Poppins-Regular; font-size: 14px;\"><li><span style=\"font-size: 11pt;\"><span style=\"font-family: Calibri, sans-serif;\"><strong style=\"font-weight: bold;\">Kerja Sama Nasional</strong></span></span><ul style=\"list-style-type: disc;\"><li><span style=\"font-size: 11pt;\"><span style=\"font-family: Calibri, sans-serif;\">Mengembangkan kemitraan dengan universitas, sekolah, dan lembaga pendidikan lainnya di dalam negeri untuk pertukaran pengetahuan, sumber daya, dan pengembangan program bersama.</span></span></li><li><span style=\"font-size: 11pt;\"><span style=\"font-family: Calibri, sans-serif;\">Menyelenggarakan seminar, lokakarya, dan acara kolaboratif dengan berbagai lembaga untuk memperkuat komunitas akademik di tingkat regional.</span></span></li><li><span style=\"font-size: 11pt;\"><span style=\"font-family: Calibri, sans-serif;\">Kerja sama dengan industri dan pemerintah daerah dalam pengembangan program pendidikan yang relevan dengan kebutuhan pasar kerja lokal.</span></span></li><li><span style=\"font-size: 11pt;\"><span style=\"font-family: Calibri, sans-serif;\">Memfasilitasi penempatan magang, kerja sama riset, dan proyek kolaboratif antara Denpasar Institute dengan perusahaan dan lembaga pemerintah daerah.</span></span></li></ul></li><li><span style=\"font-size: 11pt;\"><span style=\"font-family: Calibri, sans-serif;\"><strong style=\"font-weight: bold;\">Kerjasama Internasional</strong></span></span><ul style=\"list-style-type: disc;\"><li><span style=\"font-size: 11pt;\"><span style=\"font-family: Calibri, sans-serif;\">Mengidentifikasi peluang kolaborasi baru di tingkat internasional dalam bidang akademik, riset, dan pengembangan.</span></span></li><li><span style=\"font-size: 11pt;\"><span style=\"font-family: Calibri, sans-serif;\">Membangun dan memelihara jaringan kemitraan strategis dengan lembaga-lembaga pendidikan terkemuka di luar negeri.</span></span></li><li><span style=\"font-size: 11pt;\"><span style=\"font-family: Calibri, sans-serif;\">Merancang dan menjalankan program pertukaran pelajar, program magang, dan kerjasama penelitian bersama.</span></span></li><li><span style=\"font-size: 11pt;\"><span style=\"font-family: Calibri, sans-serif;\">Memastikan bahwa semua kegiatan dan kerjasama internasional sesuai dengan kebijakan dan regulasi yang berlaku.</span></span></li><li><span style=\"font-size: 11pt;\"><span style=\"font-family: Calibri, sans-serif;\">Mengelola administrasi terkait visa, perizinan, dan dokumen-dokumen lain yang diperlukan untuk kegiatan lintas-batas.</span></span></li><li><span style=\"font-size: 11pt;\"><span style=\"font-family: Calibri, sans-serif;\">Menyediakan dukungan administratif bagi kegiatan-kegiatan yang terkait dengan kerjasama internasional.</span></span></li><li><span style=\"font-size: 11pt;\"><span style=\"font-family: Calibri, sans-serif;\">Memfasilitasi komunikasi antara tim proyek internal dan eksternal.</span></span></li></ul></li><li><span style=\"font-size: 11pt;\"><span style=\"font-family: Calibri, sans-serif;\"><strong style=\"font-weight: bold;\">Networking</strong></span></span><ul style=\"list-style-type: disc;\"><li><span style=\"font-size: 11pt;\"><span style=\"font-family: Calibri, sans-serif;\">Membangun hubungan dengan komunitas profesional dan akademik melalui keanggotaan dalam organisasi profesi dan partisipasi dalam acara-acara industri dan akademik.</span></span></li><li><span style=\"font-size: 11pt;\"><span style=\"font-family: Calibri, sans-serif;\">Menyelenggarakan kegiatan networking dan diskusi untuk memfasilitasi pertukaran ide dan pengalaman antara anggota komunitas akademik dan profesional.</span></span></li></ul></li><li><span style=\"font-size: 11pt;\"><span style=\"font-family: Calibri, sans-serif;\"><strong style=\"font-weight: bold;\">Pengabdian kepada Masyarakat</strong></span></span><ul style=\"list-style-type: disc;\"><li><span style=\"font-size: 11pt;\"><span style=\"font-family: Calibri, sans-serif;\">Mendorong dan mendukung kegiatan pengabdian kepada masyarakat.</span></span></li><li><span style=\"font-size: 11pt;\"><span style=\"font-family: Calibri, sans-serif;\">Berkolaborasi dengan Lembaga masyarakat dan organisasi nirlaba untuk mengidentifikasi dan menanggapi kebutuhan masyarakat secara efektif.</span></span></li></ul></li></ol><p style=\"margin: 0px 0in 10px; color: rgb(0, 0, 0); font-size: 14px; font-family: Roboto, sans-serif;\"><span style=\"font-size: 11pt;\"><span style=\"font-family: Calibri, sans-serif;\">Divisi Kerja Sama dan Hubungan Internasional berperan penting untuk lebih terhubung dengan komunitas lokal, memberikan kontribusi nyata terhadap pembangunan wilayah, serta menjalankan peran sebagai agen perubahan positif dalam masyarakat.</span></span></p><p style=\"margin: 0px 0in 10px; color: rgb(0, 0, 0); font-size: 14px; font-family: Roboto, sans-serif;\"><span style=\"font-size: 11pt;\"><span style=\"font-family: Calibri, sans-serif;\">Divisi ini juga dimanfaatkan untuk membangun citra global Denpasar Institute, memperluas jaringan kerjasama, dan meningkatkan kualitas pendidikan dan riset melalui berbagai kerjasama.</span></span></p>', 'divisi_17_sections/QYSf65IIubg7lf1SsRTJIi6a8MHyQ6QCio5q2Z8F.png', 0, 'light', 'before_program', 1, '2026-07-29 17:34:58', '2026-08-02 21:56:34'),
(22, 18, 'Tentang Divisi', '<p><span style=\"color: rgb(0, 0, 0); font-family: Arial, Helvetica, sans-serif;\">Divisi </span><strong style=\"font-weight: bold; color: rgb(0, 0, 0); font-family: Arial, Helvetica, sans-serif;\">Konsultan</strong><span style=\"color: rgb(0, 0, 0); font-family: Arial, Helvetica, sans-serif;\"> di Denpasar Institute menawarkan layanan profesional yang dirancang untuk membantu individu, perusahaan, dan institusi dalam merancang strategi, mengelola, serta mengembangkan potensi mereka di berbagai bidang. Dengan tim konsultan yang berpengalaman dan memiliki keahlian di berbagai sektor, kami menyediakan solusi yang inovatif dan praktis untuk meningkatkan kinerja dan keberhasilan klien. Divisi ini mendukung klien melalui analisis mendalam, saran strategis, serta implementasi langkah-langkah praktis yang dapat mempercepat pencapaian tujuan dan mengatasi tantangan yang dihadapi.</span></p>', 'divisi_18_sections/SLd3UPbkdK1dCXmK1LE87ANQxBlU1LhOuOk77xKJ.png', 0, 'light', 'before_program', 1, '2026-07-29 17:41:12', '2026-08-02 21:57:25'),
(24, 19, 'Tentang Divisi', '<p style=\"margin: 0px 0cm 10px; color: rgb(0, 0, 0); font-size: 14px; font-family: Roboto, sans-serif;\"><span style=\"font-family: Arial, Helvetica, sans-serif;\">Divisi Karir dan Kewirausahaan, Denpasar Institute adalah divisi yang didedikasikan untuk membantu alumni SMK, alumni perguruan tinggi dan masyarakat mengembangkan karir yang tepat atau menjadikan mereka menjadi wirausahawan yang inovatif dan mandiri. Divisi ini menyediakan berbagai layanan yang dirancang untuk mempersiapkan peserta meniti karir di dunia kerja dan menciptakan peluang bisnis yang berkelanjutan.</span></p><p style=\"margin: 0px 0cm 10px; color: rgb(0, 0, 0); font-size: 14px; font-family: Roboto, sans-serif;\"><span style=\"font-family: Arial, Helvetica, sans-serif;\"><strong style=\"font-weight: bold;\">Tujuan Divisi</strong></span></p><ul style=\"color: rgb(0, 0, 0); margin-bottom: 10px; font-family: Poppins-Regular; font-size: 14px;\"><li><span style=\"font-family: Arial, Helvetica, sans-serif;\"><strong style=\"font-weight: bold;\">Meningkatkan Daya Saing Karir:</strong> Membantu peserta mengembangkan keterampilan dan kompetensi yang dibutuhkan untuk bersaing di pasar kerja yang kompetitif.</span></li><li><span style=\"font-family: Arial, Helvetica, sans-serif;\"><strong style=\"font-weight: bold;\">Mendorong Kewirausahaan:</strong> Menginspirasi dan mendukung peserta untuk menjadi wirausahawan yang inovatif, dengan menyediakan sumber daya dan bimbingan yang diperlukan untuk memulai dan mengembangkan bisnis.</span></li><li><span style=\"font-family: Arial, Helvetica, sans-serif;\"><strong style=\"font-weight: bold;\">Membangun Jaringan Profesional:</strong> Membangun jaringan profesional yang luas antara peserta, perusahaan, dan pengusaha untuk membuka lebih banyak peluang kerja dan bisnis.</span></li></ul>', 'divisi_19_sections/5et4L6dVmYw9NIQRysMa8DFUpojpXomcr6Z7vv7a.png', 0, 'light', 'before_program', 1, '2026-07-29 17:50:17', '2026-08-02 21:58:11'),
(25, 19, 'Manfaat Bagi Peserta', '<p style=\"margin: 0px 0px 10px; color: rgb(0, 0, 0); font-size: 14px; font-family: Roboto, sans-serif;\"><span style=\"font-family: Arial, Helvetica, sans-serif;\"><strong style=\"font-weight: bold;\">1. Persiapan Karir yang Lebih Baik</strong></span><br><span style=\"font-family: Arial, Helvetica, sans-serif;\">Peserta mendapatkan bimbingan langsung dari para ahli dan profesional berpengalaman, yang membantu mereka untuk lebih siap memasuki dunia kerja dengan percaya diri.</span></p><p style=\"margin: 0px 0px 10px; color: rgb(0, 0, 0); font-size: 14px; font-family: Roboto, sans-serif;\"><span style=\"font-family: Arial, Helvetica, sans-serif;\"><strong style=\"font-weight: bold;\">2. Pengembangan Keterampilan yang Diperlukan</strong></span><br><span style=\"font-family: Arial, Helvetica, sans-serif;\">Melalui berbagai pelatihan soft skills dan kewirausahaan, peserta dapat mengembangkan keterampilan penting yang diperlukan untuk sukses di dunia kerja dan bisnis.</span></p><p style=\"margin: 0px 0px 10px; color: rgb(0, 0, 0); font-size: 14px; font-family: Roboto, sans-serif;\"><span style=\"font-family: Arial, Helvetica, sans-serif;\"><strong style=\"font-weight: bold;\">3. Akses ke Peluang Kerja dan Magang</strong></span><br>​​​​​​​<span style=\"font-family: Arial, Helvetica, sans-serif;\">Dengan job placement services dan jaringan kerjasama dengan perusahaan, peserta memiliki akses yang lebih luas ke berbagai peluang kerja dan magang yang sesuai dengan bidang mereka.</span></p><p style=\"margin: 0px 0px 10px; color: rgb(0, 0, 0); font-size: 14px; font-family: Roboto, sans-serif;\"><span style=\"font-family: Arial, Helvetica, sans-serif;\"><strong style=\"font-weight: bold;\">4. Dukungan untuk Memulai Bisnis<br>​​​​​​​</strong></span><span style=\"font-family: Arial, Helvetica, sans-serif;\">Bagi peserta yang tertarik untuk menjadi wirausahawan, Divisi Karir dan Kewirausahaan menyediakan dukungan yang komprehensif, mulai dari mentoring, pelatihan, hingga akses ke investor.</span></p><p style=\"margin: 0px 0px 10px; color: rgb(0, 0, 0); font-size: 14px; font-family: Roboto, sans-serif;\"><span style=\"font-family: Arial, Helvetica, sans-serif;\"><strong style=\"font-weight: bold;\">5. Peluang untuk Mengembangkan Jaringan</strong></span><br>​​​​​​​<span style=\"font-family: Arial, Helvetica, sans-serif;\">Peserta memiliki kesempatan untuk memperluas jaringan profesional mereka, baik melalui kegiatan yang diadakan oleh divisi ini maupun melalui program kerjasama dengan berbagai perusahaan dan organisasi.</span></p><p style=\"margin: 0px 0cm 10px; color: rgb(0, 0, 0); font-size: 14px; font-family: Roboto, sans-serif;\"><span style=\"font-family: Arial, Helvetica, sans-serif;\"><strong style=\"font-weight: bold;\">Peluang Bisnis Setelah Mengikuti Program</strong></span></p><p style=\"margin: 0px 0px 10px; color: rgb(0, 0, 0); font-size: 14px; font-family: Roboto, sans-serif;\"><span style=\"font-family: Arial, Helvetica, sans-serif;\"><strong style=\"font-weight: bold;\">1. Memulai Usaha Sendiri</strong></span><br>​​​​​​​<span style=\"font-family: Arial, Helvetica, sans-serif;\">Peserta yang mengikuti program inkubator bisnis akan memiliki pengetahuan dan keterampilan yang diperlukan untuk memulai dan mengelola usaha sendiri. Dengan dukungan dari mentor dan akses ke investor, peserta dapat mewujudkan ide bisnis mereka menjadi kenyataan, baik dalam bentuk startup teknologi, usaha kecil menengah (UKM), atau bisnis kreatif.</span></p><p style=\"margin: 0px 0px 10px; color: rgb(0, 0, 0); font-size: 14px; font-family: Roboto, sans-serif;\"><span style=\"font-family: Arial, Helvetica, sans-serif;\"><strong style=\"font-weight: bold;\">2. Mitra Bisnis dan Jaringan</strong></span><br><span style=\"font-family: Arial, Helvetica, sans-serif;\">Melalui program ini, peserta dapat membangun jaringan yang luas dengan sesama pengusaha, investor, dan profesional lainnya. Jaringan ini dapat membuka peluang untuk kolaborasi bisnis, baik dalam bentuk kemitraan, usaha bersama, atau dukungan pemasaran.</span></p><p style=\"margin: 0px 0px 10px; color: rgb(0, 0, 0); font-size: 14px; font-family: Roboto, sans-serif;\"><span style=\"font-family: Arial, Helvetica, sans-serif;\"><strong style=\"font-weight: bold;\">3. Peluang Lisensi dan Waralaba</strong></span><br><span style=\"font-family: Arial, Helvetica, sans-serif;\">Bagi peserta yang berhasil mengembangkan bisnis yang sukses, terdapat peluang untuk memperluas usaha melalui model lisensi atau waralaba. Divisi Karir dan Kewirausahaan dapat memberikan panduan dalam mengembangkan model bisnis yang dapat direplikasi oleh mitra lain di berbagai lokasi.</span></p><p style=\"margin: 0px 0px 10px; color: rgb(0, 0, 0); font-size: 14px; font-family: Roboto, sans-serif;\"><span style=\"font-family: Arial, Helvetica, sans-serif;\"><strong style=\"font-weight: bold;\">4. Pelatihan dan Konsultasi<br>​​​​​​​</strong></span><span style=\"font-family: Arial, Helvetica, sans-serif;\">Peserta yang telah berpengalaman dan sukses dalam bisnis juga berpeluang untuk menjadi mentor atau konsultan bagi pengusaha pemula lainnya. Ini tidak hanya membuka peluang bisnis baru dalam bentuk pelatihan dan konsultasi, tetapi juga membantu memperkuat ekosistem kewirausahaan di Bali.</span></p><p style=\"margin: 0px 0px 10px; color: rgb(0, 0, 0); font-size: 14px; font-family: Roboto, sans-serif;\"><span style=\"font-family: Arial, Helvetica, sans-serif;\">Dengan mengikuti program-program yang disediakan oleh <strong style=\"font-weight: bold;\">Divisi Karir dan Kewirausahaan</strong> di Denpasar Institute, peserta tidak hanya akan siap menghadapi dunia kerja, tetapi juga memiliki landasan yang kuat untuk menjadi wirausahawan sukses yang mampu berkontribusi pada pertumbuhan ekonomi lokal dan nasional.</span></p>', NULL, 0, 'accent', 'before_program', 1, '2026-07-29 17:50:55', '2026-07-29 17:50:55');

-- --------------------------------------------------------

--
-- Table structure for table `events`
--

CREATE TABLE `events` (
  `id` bigint UNSIGNED NOT NULL,
  `kategori` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `kontributor` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `no_anggota` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `published_at` datetime DEFAULT NULL,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `content` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `image` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `views` int NOT NULL DEFAULT '0',
  `is_active` tinyint(1) NOT NULL DEFAULT '0',
  `status` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `created_by` bigint UNSIGNED DEFAULT NULL,
  `approved_by` bigint UNSIGNED DEFAULT NULL,
  `approved_at` timestamp NULL DEFAULT NULL,
  `rejection_note` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Table structure for table `failed_jobs`
--

CREATE TABLE `failed_jobs` (
  `id` bigint UNSIGNED NOT NULL,
  `uuid` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `connection` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `queue` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `payload` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `exception` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `failed_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Table structure for table `hero_sliders`
--

CREATE TABLE `hero_sliders` (
  `id` bigint UNSIGNED NOT NULL,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `subtitle` text COLLATE utf8mb4_unicode_ci,
  `background_image` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `logo_image` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `button_text` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Selengkapnya',
  `button_url` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '#',
  `stats` json DEFAULT NULL,
  `order` int NOT NULL DEFAULT '0',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `type` enum('banner','divisi') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'divisi',
  `divisi_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

