INSERT INTO `hero_sliders` (`id`, `title`, `subtitle`, `background_image`, `logo_image`, `button_text`, `button_url`, `stats`, `order`, `is_active`, `type`, `divisi_name`, `created_at`, `updated_at`) VALUES
(1, '9 Divisi Aktif Denpasar Institute', 'Satu ekosistem lengkap mulai dari riset ilmiah, publikasi, pengembangan SDM, teknologi, budaya, hingga kewirausahaan. Transforming Ideas into Action.', 'slider/backgrounds/2yaIckcILvcD1bgTqw2clr9TOFrsGJLcoTnILUpm.png', NULL, 'Selengkapnya', '#', '[]', 1, 1, 'banner', NULL, '2026-07-28 23:10:58', '2026-08-02 16:43:14'),
(2, 'Divisi Riset dan Inovasi', 'Mendorong penelitian berkualitas tinggi dan inovasi berbasis bukti untuk kemajuan institusi dan masyarakat luas.', 'slider/backgrounds/UsycYhpajww6hafpFMPjUh6lEDlIrNKc8u1tO3ml.png', 'slider/logos/1UDLKrbtPvCdxnzk9p2MWlEcJ28hgHBROk1AxBuT.png', 'Selengkapnya', '/divisi/divisi-riset-dan-inovasi', '[{\"label\": \"Proyek Riset\", \"number\": \"50+\"}, {\"label\": \"Inovasi\", \"number\": \"25+\"}, {\"label\": \"Peneliti\", \"number\": \"100+\"}]', 2, 1, 'divisi', 'Riset dan Inovasi', '2026-07-28 23:10:58', '2026-08-02 16:49:57'),
(3, 'Divisi Publikasi dan HKI', 'Mengelola penerbitan jurnal, buku, serta layanan Hak Kekayaan Intelektual dan paten profesional.', 'slider/backgrounds/48lkSN0z1xn5KQYAqtnQAq3P5P0ysu4PCximGuEx.png', 'slider/logos/Q4LfgVsNzTATVo89R5o1l4kaDmoksxWy9UUw2hU4.png', 'Selengkapnya', '/divisi/divisi-publikasi-dan-hki', '[{\"label\": \"Jurnal\", \"number\": \"30+\"}, {\"label\": \"HKI Terdaftar\", \"number\": \"200+\"}, {\"label\": \"Paten\", \"number\": \"15+\"}]', 3, 1, 'divisi', 'Publikasi dan HKI', '2026-07-28 23:10:58', '2026-08-02 18:11:53'),
(4, 'Divisi Pengembangan SDM', 'Pelatihan, workshop, dan seminar untuk meningkatkan kompetensi sumber daya manusia yang berdaya saing global.', 'slider/backgrounds/k8xZ7DWR4bmIdWO50EcaYCxdi8AU7b7XXyLq99kW.png', 'slider/logos/tHZ9h213NFFyqfa0OnXO32NlyM7VO6dKDY6ZaAlS.png', 'Selengkapnya', '/divisi/divisi-pengembangan-sdm', '[{\"label\": \"Peserta/Tahun\", \"number\": \"500+\"}, {\"label\": \"Program\", \"number\": \"40+\"}, {\"label\": \"Kepuasan\", \"number\": \"95%\"}]', 4, 1, 'divisi', 'Pengembangan SDM', '2026-07-28 23:10:58', '2026-08-02 18:13:05'),
(5, 'Divisi Vokasi & Sertifikasi', 'Pendidikan vokasi dan program sertifikasi berstandar nasional dan internasional untuk kesiapan karir profesional.', 'slider/backgrounds/xmLHPA6XUO9CXxc54GHlu6AkYOvVYcGXpxEp192h.png', 'slider/logos/4zSmoTHtAGxA8h5uTLHb8wDZlQpPTFn6Jg20Cl6m.png', 'Selengkapnya', '/divisi/divisi-vokasi-dan-sertifikasi', '[{\"label\": \"Skema Sertifikasi\", \"number\": \"20+\"}, {\"label\": \"Lulusan\", \"number\": \"1000+\"}, {\"label\": \"Terserap Kerja\", \"number\": \"90%\"}]', 5, 1, 'divisi', 'Vokasi dan Sertifikasi', '2026-07-28 23:10:58', '2026-08-02 18:17:42'),
(6, 'Divisi Sains Data & Teknologi', 'Solusi big data, artificial intelligence, dan transformasi digital untuk institusi modern dan berkelanjutan.', 'slider/backgrounds/csgukmNPvY5XLwnPf2ZmVVYyI7QqyCPyTAahM3Ba.png', 'slider/logos/x51Bubn7r2YqadS3emF1bUp1HE9iBJtSHNpbEcaB.png', 'Selengkapnya', '/divisi/divisi-sains-data-dan-ti', '[{\"label\": \"Proyek AI\", \"number\": \"100+\"}, {\"label\": \"Klien\", \"number\": \"50+\"}, {\"label\": \"Support\", \"number\": \"24/7\"}]', 6, 1, 'divisi', 'Sains Data dan Teknologi', '2026-07-28 23:10:58', '2026-08-02 18:18:52'),
(7, 'Divisi Bahasa, Seni & Budaya', 'Pelestarian bahasa, riset budaya, dan digitalisasi warisan budaya Indonesia untuk generasi mendatang.', 'slider/backgrounds/2PXLH5H3qEwXPievjF9VK4YB2VhyyfEpGDVsFU46.png', 'slider/logos/Stc2NaCVNMI6tre2YFYuFIpEN1XxBwNvGtQ14M5V.png', 'Selengkapnya', '/divisi/divisi-bahasa-seni-dan-budaya', '[{\"label\": \"Bahasa\", \"number\": \"10+\"}, {\"label\": \"Riset Budaya\", \"number\": \"50+\"}, {\"label\": \"Artefak Digital\", \"number\": \"500+\"}]', 7, 1, 'divisi', 'Bahasa, Seni dan Budaya', '2026-07-28 23:10:58', '2026-08-02 18:20:25'),
(8, 'Divisi Kerja Sama dan HI', 'Kemitraan global, pertukaran ilmu pengetahuan, beasiswa, dan kolaborasi riset internasional.', 'slider/backgrounds/JvMLQrPC6o0o8gIcaMrbaRTLwwlpMGgElsLWrhvo.png', 'slider/logos/cQO4ha0qWhroMSQ0y7qkEFqsl9437afObePGU3PJ.png', 'Selengkapnya', '/divisi/divisi-kerja-sama-dan-hi', '[{\"label\": \"Mitra Global\", \"number\": \"30+\"}, {\"label\": \"Negara\", \"number\": \"15+\"}, {\"label\": \"Kolaborasi\", \"number\": \"200+\"}]', 8, 1, 'divisi', 'Kerja Sama dan HI', '2026-07-28 23:10:58', '2026-08-02 18:21:31'),
