(10, 'Divisi Karir & Kewirausahaan', 'Inkubasi bisnis, program wirausaha, dan pendampingan startup untuk generasi muda yang inovatif.', 'slider/backgrounds/p7l3zrKeBuiwoK64B4y2C2QR5LqHSu27XbDEbfvX.jpg', 'slider/logos/TgYGSH06cCNgPYtpKupwp548mwEtKhxrl6eHCnsl.png', 'Selengkapnya', '/divisi/divisi-karir-dan-kewirausahaan', '[{\"label\": \"Startup\", \"number\": \"50+\"}, {\"label\": \"Wirausaha\", \"number\": \"300+\"}, {\"label\": \"Berhasil\", \"number\": \"85%\"}]', 10, 1, 'divisi', 'Karir dan Kewirausahaan', '2026-07-28 23:10:58', '2026-08-02 18:24:23');

