(33, 14, 'Bimbel', 'bimbel', NULL, '<p style=\"margin: 0px 0px 10px; color: rgb(0, 0, 0); font-family: Poppins-Regular; text-align: justify; font-size: 18px !important;\"><strong style=\"font-weight: bold;\">Denpasar Institute</strong> menghadirkan bimbingan belajar sebagai alternatif pendekatan belajar yang berbasis minat individu pembelajar dan menghindarkan anak dari kasus bullying. Ingat, sukses tidak hanya didapatkan dari belajar di sekolah atau kampus tetapi bisa dimulai dari bimbingan belajar. &nbsp;&nbsp;</p><p style=\"margin: 0px 0px 10px; color: rgb(0, 0, 0); font-family: Poppins-Regular; text-align: justify; font-size: 18px !important;\">Keunggulan bimbingan belajar dari Denpasar Institute adalah:</p><ol style=\"color: rgb(0, 0, 0); margin-bottom: 10px; font-family: Poppins-Regular; font-size: 14px;\"><li style=\"text-align: justify;\"><span style=\"font-size: 18px;\">Jadwal belajar berdasarkan kesepakatan</span></li><li style=\"text-align: justify;\"><span style=\"font-size: 18px;\">Proses belajar mengajar yang menyenangkan</span></li><li style=\"text-align: justify;\"><span style=\"font-size: 18px;\">Pengajar profesional dan bertalenta sehingga pembelajaran lebih kreatif dan partisipatif</span></li><li style=\"text-align: justify;\"><span style=\"font-size: 18px;\">Mengimplementasikan kurikulum secara tidak kaku&nbsp;</span></li><li style=\"text-align: justify;\"><span style=\"font-size: 18px;\">Terhindar dari kasus bullying&nbsp;</span></li><li style=\"text-align: justify;\"><span style=\"font-size: 18px;\">Melibatkan orang tua/wali untuk menumbuhkembangkan karakter anak</span></li><li style=\"text-align: justify;\"><span style=\"font-size: 18px;\">Perhatian belajar fokus pada bakat dan minat anak</span></li><li style=\"text-align: justify;\"><span style=\"font-size: 18px;\">Mengedepankan kreatifitas dalam proses belajar mengajar</span></li></ol><p style=\"margin: 0px 0px 10px; color: rgb(0, 0, 0); font-family: Poppins-Regular; text-align: justify; font-size: 18px !important;\">untuk rincian biaya, klik<a href=\"http://denpasarinstitute.com/download\" style=\"background-color: transparent; color: rgb(51, 122, 183);\"> link ini</a></p><p style=\"margin: 0px 0px 10px; color: rgb(0, 0, 0); font-family: Poppins-Regular; text-align: justify; font-size: 18px !important;\"><strong style=\"font-weight: bold;\">Hubungi kami untuk jadwalkan diskusi lebih lanjut tentang program ini</strong></p>', 1, 0, '2026-07-29 17:09:50', '2026-07-29 17:09:50');
INSERT INTO `programs` (`id`, `divisi_id`, `nama`, `slug`, `ikon`, `deskripsi`, `is_active`, `urutan`, `created_at`, `updated_at`) VALUES
(34, 14, 'Homeschooling', 'homeschooling', NULL, '<p style=\"margin: 0px 0px 10px; color: rgb(0, 0, 0); font-family: Poppins-Regular; text-align: justify; font-size: 18px !important;\">Hasil studi tentang <strong style=\"font-weight: bold;\"><em>Childcare Quality and Child Development</em></strong> yang termuat di <strong style=\"font-weight: bold;\"><em>the Journal of Human Resources Vol. 54 No. 3 Tahun 2019</em></strong> secara implisit menunjukkan bahwa interaksi dan komunikasi yang berkualitas di masa kecil berpengaruh terhadap perkembangan anak sebagai <strong style=\"font-weight: bold;\"><em>future leaders</em></strong>.&nbsp; Interaksi dan komunikasi yang berkualitas membutuhkan pendekatan pembelajaran komprehensif sesuai bakat dan potensi individu anak.</p><p style=\"margin: 0px 0px 10px; color: rgb(0, 0, 0); font-family: Poppins-Regular; text-align: justify; font-size: 18px !important;\">Pendekatan pembelajaran kolektif di sekolah formal cenderung kurang memerhatikan bakat dan&nbsp; potensi individu anak.&nbsp;</p><p style=\"margin: 0px 0px 10px; color: rgb(0, 0, 0); font-family: Poppins-Regular; text-align: justify; font-size: 18px !important;\"><strong style=\"font-weight: bold;\">Homeschooling</strong> merupakan kegiatan belajar mengajar yang dilakukan di rumah dengan fokus perhatian pembelajaran berbasis bakat dan individu anak.&nbsp;</p><p style=\"margin: 0px 0px 10px; color: rgb(0, 0, 0); font-family: Poppins-Regular; text-align: justify; font-size: 18px !important;\">Denpasar Institute turut mengambil peran untuk membentuk SDM unggul sedari awal dengan membuka program <strong style=\"font-weight: bold;\"><em>homeschooling.</em></strong>&nbsp;</p><p style=\"margin: 0px 0px 10px; color: rgb(0, 0, 0); font-family: Poppins-Regular; text-align: justify; font-size: 18px !important;\"><strong style=\"font-weight: bold;\">Denpasar Institute</strong> menghadirkan homeschooling sebagai alternatif pendekatan belajar yang berbasis minat individu pembelajar dan menghindarkan anak dari kasus <strong style=\"font-weight: bold;\"><em>bullying</em></strong>. Ingat, membentuk SDM unggul perlu memerhatikan pendidikan formal, non formal dan informal. &nbsp;&nbsp;</p><p style=\"margin: 0px 0px 10px; color: rgb(0, 0, 0); font-family: Poppins-Regular; text-align: justify; font-size: 18px !important;\">Berbagai keunggulan <strong style=\"font-weight: bold;\"><em>homeschooling</em></strong> yang kami tawarkan adalah:&nbsp;</p><ul style=\"color: rgb(0, 0, 0); margin-bottom: 10px; font-family: Poppins-Regular; font-size: 14px;\"><li style=\"text-align: justify;\"><span style=\"font-size: 18px;\">Jadwal belajar berdasarkan kesepakatan</span></li><li style=\"text-align: justify;\"><span style=\"font-size: 18px;\">Proses belajar mengajar yang menyenangkan</span></li><li style=\"text-align: justify;\"><span style=\"font-size: 18px;\">Pengajar profesional dan bertalenta sehingga pembelajaran lebih kreatif dan partisipatif</span></li><li style=\"text-align: justify;\"><span style=\"font-size: 18px;\">Mengimplementasikan kurikulum secara fleksibel dan bertumpu pada mutu pembelajaran</span></li><li style=\"text-align: justify;\"><span style=\"font-size: 18px;\">Terhindar dari kasus <strong style=\"font-weight: bold;\"><em>bullying</em></strong>&nbsp;</span></li><li style=\"text-align: justify;\"><span style=\"font-size: 18px;\">Melibatkan orang tua/wali untuk menumbuhkembangkan karakter anak</span></li><li style=\"text-align: justify;\"><span style=\"font-size: 18px;\">Perhatian belajar fokus pada bakat dan minat anak</span></li><li style=\"text-align: justify;\"><span style=\"font-size: 18px;\">Mengedepankan kreatifitas dalam proses interaksi belajar mengajar</span></li></ul><p style=\"margin: 0px 0px 10px; color: rgb(0, 0, 0); font-family: Poppins-Regular; text-align: justify; font-size: 18px !important;\">Kami memahami dan meyakini bahwa <strong style=\"font-weight: bold;\"><em>Homeschooling</em></strong> dapat menjadi alternatif pendidikan berbasis kolaborasi guru-orang tua dalam <strong style=\"font-weight: bold;\"><em>blended learning</em></strong> yang memungkinkan anak berkembang sesuai dengan potensinya masing-masing.&nbsp;</p><p style=\"margin: 0px 0px 10px; color: rgb(0, 0, 0); font-family: Poppins-Regular; text-align: justify; font-size: 18px !important;\">untuk rincian biaya, klik<a href=\"http://denpasarinstitute.com/download\" style=\"background-color: transparent; color: rgb(51, 122, 183);\"> link ini</a></p><p style=\"margin: 0px 0px 10px; color: rgb(0, 0, 0); font-family: Poppins-Regular; text-align: justify; font-size: 18px !important;\"><strong style=\"font-weight: bold;\">Hubungi kami untuk jadwalkan diskusi lebih lanjut tentang program ini&nbsp;</strong></p>', 1, 0, '2026-07-29 17:10:22', '2026-07-29 17:10:22'),
(35, 15, 'Jurnal Ilmiah', 'jurnal-ilmiah', NULL, '<p style=\"margin: 0px 0cm 10px; color: rgb(0, 0, 0); font-family: Poppins-Regular; text-align: justify; font-size: 18px !important;\"><span style=\"font-size: 12pt;\"><span style=\"font-size: 18px !important;\"><span style=\"font-family: &quot;Times New Roman&quot;, serif;\"><span style=\"font-size: 18pt; font-family: Poppins-Regular !important;\"><span style=\"font-family: Arial, &quot;sans-serif&quot;; font-size: 18px !important;\"><span style=\"color: rgb(32, 33, 34); font-family: Poppins-Regular !important;\"><strong style=\"font-weight: bold;\"><em>Data history</em></strong> dalam wujud artikel ilmiah merupakan bagian penting dari perjalanan riset seseorang. Publikasi hasil riset merupakan \'roh\' bagi seorang periset. Untuk menjembatani proses ini, Pusat Sains Data dan Teknologi Informasi, </span></span></span><span style=\"font-size: 18pt; font-family: Poppins-Regular !important;\"><span style=\"font-size: 18px !important;\"><span style=\"font-family: Arial, &quot;sans-serif&quot;;\"><span style=\"color: rgb(32, 33, 36); font-family: Poppins-Regular !important;\">Denpasar Institute mengelola <em>data history </em>para periset di berbagai jurnal ilmiah yang diterbitkan secara berkala.</span></span></span></span></span></span></span></p><p style=\"margin: 0px 0cm 10px; color: rgb(0, 0, 0); font-family: Poppins-Regular; text-align: justify; font-size: 18px !important;\"><span style=\"font-size: 12pt;\"><span style=\"font-size: 18px !important;\"><span style=\"font-family: &quot;Times New Roman&quot;, serif;\"><span style=\"font-size: 18pt; font-family: Poppins-Regular !important;\"><span style=\"font-size: 18px !important;\"><span style=\"font-family: Arial, &quot;sans-serif&quot;;\"><span style=\"color: rgb(32, 33, 36); font-family: Poppins-Regular !important;\">Jurnal ilmiah Denpasar Institute memuat artikel ilmiah sebagai luaran hasil riset dari profesor, dosen, guru, mahasiswa, periset dan para praktisi.</span></span></span></span></span></span></span></p><p style=\"margin: 0px 0cm 10px; color: rgb(0, 0, 0); font-family: Poppins-Regular; text-align: justify; font-size: 18px !important;\"><span style=\"font-size: 11pt;\"><span style=\"font-family: Calibri, sans-serif; font-size: 18px !important;\"><span style=\"font-size: 18pt; font-family: Poppins-Regular !important;\"><span style=\"font-size: 18px !important;\"><span style=\"font-family: Arial, &quot;sans-serif&quot;;\"><span style=\"color: rgb(32, 33, 34); font-family: Poppins-Regular !important;\">Jurnal ilmiah terbitan Denpasar Institute dikelola oleh <em>journal managers, editors, reviewers</em> dan staf admin dengan latar keilmuan sesuai <em>journal scope</em>. Ini dilakukan untuk menjaga mutu dan profesionalisme terbitan jurnal agar sesuai dengan </span></span></span></span><span style=\"font-size: 18pt; font-family: Poppins-Regular !important;\"><span style=\"font-family: Arial, &quot;sans-serif&quot;; font-size: 18px !important;\"><span style=\"color: rgb(32, 33, 34); font-family: Poppins-Regular !important;\">aturan dan standar etika kepenulisan dan bebas dari konflik kepentingan.</span></span></span></span></span></p><p style=\"margin: 0px 0cm 10px; color: rgb(0, 0, 0); font-family: Poppins-Regular; text-align: justify; font-size: 18px !important;\"><span style=\"font-size: 11pt;\"><span style=\"font-family: Calibri, sans-serif; font-size: 18px !important;\"><span style=\"font-size: 18pt; font-family: Poppins-Regular !important;\"><span style=\"font-family: Arial, &quot;sans-serif&quot;; font-size: 18px !important;\">Kami menyampaikan terima kasih banyak atas kesediaan dan kepercayaan Bapak/Ibu yang bergabung bersama kami untuk mengelola jurnal ilmiah terbitan Denpasar Institute, Lembaga Riset &amp; Pengembangan SDM.</span></span></span></span></p><p style=\"margin: 0px 0cm 10px; color: rgb(0, 0, 0); font-family: Poppins-Regular; text-align: justify; font-size: 18px !important;\"><span style=\"font-size: 11pt;\"><span style=\"font-family: Calibri, sans-serif; font-size: 18px !important;\"><span style=\"font-size: 18pt; font-family: Poppins-Regular !important;\"><span style=\"font-family: Arial, &quot;sans-serif&quot;; font-size: 18px !important;\">Saat ini dua jurnal ilmiah terbitan Denpasar Institute sedang proses akreditasi dan beberapa lainnya dalam proses pengembangan untuk pengajuan ISSN. kami masih proses rekrutmen <em>editors</em> dan <em>reviewers</em> dengan klik <a href=\"https://bit.ly/jurnal_DI\" style=\"background-color: transparent; color: rgb(51, 122, 183);\">Editors &amp; Reviewers Denpasar Institute</a></span></span></span></span></p><p style=\"margin: 0px 0cm 10px; color: rgb(0, 0, 0); font-family: Poppins-Regular; text-align: justify; font-size: 18px !important;\"><span style=\"font-size: 11pt;\"><span style=\"font-family: Calibri, sans-serif; font-size: 18px !important;\"><span style=\"font-size: 18pt; font-family: Poppins-Regular !important;\"><span style=\"font-family: Arial, &quot;sans-serif&quot;; font-size: 18px !important;\">Denpasar Institute memberikan <em>benefits</em> kepada <em>editors</em> dan <em>reviewers </em>berupa:</span></span></span></span></p><p style=\"margin: 0px 0cm 10px; color: rgb(0, 0, 0); font-family: Poppins-Regular; font-size: 18px !important; text-align: justify !important;\"><span style=\"font-size: 11pt;\"><span style=\"font-family: Calibri, sans-serif; font-size: 18px !important;\"><span style=\"font-size: 18pt; font-family: Poppins-Regular !important;\"><span style=\"font-family: Arial, &quot;sans-serif&quot;; font-size: 18px !important;\">- SK Editor dan/atau Reviewer</span></span></span></span></p><p style=\"margin: 0px 0cm 10px; color: rgb(0, 0, 0); font-family: Poppins-Regular; font-size: 18px !important; text-align: justify !important;\"><span style=\"font-size: 11pt;\"><span style=\"font-family: Calibri, sans-serif; font-size: 18px !important;\"><span style=\"font-size: 18pt; font-family: Poppins-Regular !important;\"><span style=\"font-family: Arial, &quot;sans-serif&quot;; font-size: 18px !important;\">- KTA Konsultan Denpasar Institute</span></span></span></span></p><p style=\"margin: 0px 0cm 10px; color: rgb(0, 0, 0); font-family: Poppins-Regular; font-size: 18px !important; text-align: justify !important;\"><span style=\"font-size: 11pt;\"><span style=\"font-family: Calibri, sans-serif; font-size: 18px !important;\"><span style=\"font-size: 18pt; font-family: Poppins-Regular !important;\"><span style=\"font-family: Arial, &quot;sans-serif&quot;; font-size: 18px !important;\">- Jejaring Periset berlatar Akademisi dan Praktisi</span></span></span></span></p><p style=\"margin: 0px 0cm 10px; color: rgb(0, 0, 0); font-family: Poppins-Regular; font-size: 18px !important; text-align: justify !important;\"><span style=\"font-size: 11pt;\"><span style=\"font-family: Calibri, sans-serif; font-size: 18px !important;\"><span style=\"font-size: 18pt; font-family: Poppins-Regular !important;\"><span style=\"font-family: Arial, &quot;sans-serif&quot;; font-size: 18px !important;\">- Ruang Ekspresi dan Kreatifitas Ilmiah</span></span></span></span></p><p style=\"margin: 0px 0cm 10px; color: rgb(0, 0, 0); font-family: Poppins-Regular; text-align: justify; font-size: 18px !important;\"><span style=\"font-size: 11pt;\"><span style=\"font-family: Calibri, sans-serif; font-size: 18px !important;\"><span style=\"font-size: 18pt; font-family: Poppins-Regular !important;\"><span style=\"font-family: Arial, &quot;sans-serif&quot;; font-size: 18px !important;\">Daftar jurnal yang sudah dikelola dan yang proses pengembangan OJS adalah sebagai berikut.</span></span></span></span></p><ul style=\"color: rgb(0, 0, 0); margin-bottom: 10px; font-family: Poppins-Regular; font-size: 14px;\"><li><span style=\"font-size: 11pt; text-align: justify !important;\"><span style=\"font-family: Calibri, sans-serif; font-size: 18px !important;\"><span style=\"font-size: 18pt; font-family: Poppins-Regular !impor